        /// The end of the 24th calendar month after the flight review's (61.56(c)).
        var flightReviewUntil: String?
        /// YYYY-MM-DD; null where none can be had.
        var medicalExpiresOn: String?
        /// Every entry's hours, to the tenth.
        var totalHours: Double
        /// To the tenth.
        var nightHours: Double
        /// To the tenth.
        var crossCountryHours: Double
        var landings: Int
        var flights: Int
        /// The last day of instrument currency (61.57(c)(1), or 61.57(d)'s check); in the past where it has lapsed, null where none is logged.
        var instrumentCurrentUntil: String?
        /// The first day of an instrument currency not begun yet: approaches, holding and tracking flown this month count from the first of next month (61.57(c)(1), 'the 6 calendar months preceding the month of the flight'), so until then the pilot is not current and instrumentCurrentUntil is the end of the currency to come. Null when current now, lapsed or none logged.
        var instrumentCurrentFrom: String?
        /// YYYY-MM-DD; null where none can be had.
        var ipcOn: String?
        /// The day after which only an instrument proficiency check restores it: six calendar months past instrumentCurrentUntil (61.57(d)).
        var ipcNeededAfter: String?
        /// Approaches logged in the 6 calendar months before this one (61.57(c)(1)(i)).
        var approachesInWindow: Int
        /// Holding logged in them (61.57(c)(1)(ii)).
        var holdingInWindow: Bool
        /// Intercepting and tracking courses logged in them (61.57(c)(1)(iii)).
        var trackingInWindow: Bool
    }

