    struct VerdictInputRunways: Codable, Equatable, Sendable {
        /// Read as JavaScript reads it: missing, null, false, 0 and "" are false.
        var pending: Bool?
        /// Read as JavaScript reads it: missing, null, false, 0 and "" are false.
        var worked: Bool?
        var short: [String]?
        var crosswind: [String]?
        /// Fields whose distances were read past the POH's table: a caution.
        var beyond: [String]?
        /// Fields whose distances could not be held to the runway (its length or the field's elevation not known): unknown, never ok.
        var unchecked: [String]?
    }

    struct VerdictInputWeather: Codable, Equatable, Sendable {
        /// Read as JavaScript reads it: missing, null, false, 0 and "" are false.
        var pending: Bool?
        /// The briefing failed, in words.
        var failed: String?
        /// AIM 7-1-5's "VFR flight not recommended", its reasons.
        var vfrNotRecommended: [String]?
        /// Under the pilot's own minimums (gonogo_under_minimums).
        var underMinimums: [String]?
        /// Icing possible at an altitude flown, in a line (gonogo_icing).
        var icing: String?
        /// SIGMETs and G-AIRMETs along the route, by name.
        var hazards: [String]?
        /// Sources that did not answer, by name.
        var unchecked: [String]?
        /// The worst the forecast says along the route, in words.
        var worst: String?
        /// ITWS alerts in force now at the route's airports, each in its words with its airport (AIM 4-3-7).
        var terminalAlerts: [String]?
        /// The Command Center's ground stops and delay programs at the route's airports, in words; a finding under IFR only.
        var flowPrograms: [String]?
        /// The flight is planned IFR. Read as JavaScript reads it: missing, null, false, 0 and "" are false.
        var ifr: Bool?

        enum CodingKeys: String, CodingKey {
            case pending
            case failed
            case vfrNotRecommended = "vfr_not_recommended"
            case underMinimums = "under_minimums"
            case icing
            case hazards
            case unchecked
            case worst
            case terminalAlerts = "terminal_alerts"
            case flowPrograms = "flow_programs"
            case ifr
        }
    }

